import fs from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {globalCellId} from './scripts/prompt19-joined-topology.mjs';
const root = 'data/derived/prompt19/mixed-world-v2-7bb8d40b5113b6cff987';
const metrics = JSON.parse(gunzipSync(fs.readFileSync(root + '/metrics.json.gz')));
const metricsById = new Map(metrics.map(x => [x.id, x]));
const candidates = {KOR:'joined-v2-652d25d95ef0a040c72e',PRK:'joined-v2-982801207a60f262ad74'};
const out = {};
for (const country of ['KOR','PRK']) {
  const cells = JSON.parse(fs.readFileSync('data/derived/prompt19/candidates/' + country + '/' + candidates[country] + '/cells.geojson')).features;
  const byId = new Map(cells.map(x => [globalCellId(x), x.properties]));
  const rows = metrics.filter(x => x.sourceCountryId === country);
  const areas = rows.map(x => x.areaKm2).sort((a,b) => a-b);
  const sum = areas.reduce((a,b) => a+b,0);
  const q = p => areas[Math.floor((areas.length-1)*p)];
  let cumulative=0, weightedMedian=0;
  for (const area of areas) {cumulative += area; if(cumulative >= sum/2) {weightedMedian=area;break;}}
  const main=areas.filter(x => x >= 1);
  const groups={};
  for(const cell of cells) {
    const basis=cell.properties.boundaryBasis;
    const group=groups[basis] ??= {count:0,areaKm2:0,under1:0};
    const area=metricsById.get(globalCellId(cell)).areaKm2;
    group.count++;group.areaKm2+=area;if(area<1)group.under1++;
  }
  out[country]={
    count:areas.length,totalAreaKm2:sum,meanAreaKm2:sum/areas.length,
    quantilesKm2:{min:q(0),p25:q(.25),p50:q(.5),p75:q(.75),p90:q(.9),p95:q(.95),max:q(1)},
    atLeast1Km2:{count:main.length,p50:main[Math.floor((main.length-1)/2)],mean:main.reduce((a,b)=>a+b,0)/main.length},
    areaWeightedMedianKm2:weightedMedian,
    under1Km2:{count:areas.filter(x=>x<1).length,areaShare:areas.filter(x=>x<1).reduce((a,b)=>a+b,0)/sum},
    over100Km2:{count:areas.filter(x=>x>100).length,areaShare:areas.filter(x=>x>100).reduce((a,b)=>a+b,0)/sum},
    over500Km2Count:areas.filter(x=>x>500).length,
    uniqueFineSourceFeatures:new Set(cells.filter(x=>x.properties.fineSourceIdentity).map(x=>x.properties.sourceFeatureId)).size,
    byBoundaryBasis:groups,
    largestFive:rows.sort((a,b)=>b.areaKm2-a.areaKm2).slice(0,5).map(x=>({name:byId.get(x.id)?.name,areaKm2:x.areaKm2,adminLevel:byId.get(x.id)?.adminLevel,boundaryBasis:byId.get(x.id)?.boundaryBasis}))
  };
}
console.log(JSON.stringify(out,null,2));

